# Get all restaurants in Paris
all_restaurants = get_all_restaurants_in_city("Paris")

# Get all hotels in Paris
all_hotels = get_all_hotels_in_city("Paris")

# Get the top-rated restaurant and hotel
top_rated_restaurant = None
top_rated_hotel = None

for restaurant in all_restaurants.split(","):
    if top_rated_restaurant is None:
        top_rated_restaurant = restaurant
    else:
        restaurant_rating = get_rating_reviews_for_restaurants([restaurant])
        top_rated_restaurant_rating = get_rating_reviews_for_restaurants([top_rated_restaurant])
        if restaurant in restaurant_rating and top_rated_restaurant in top_rated_restaurant_rating:
            if restaurant_rating[restaurant] > top_rated_restaurant_rating[top_rated_restaurant]:
                top_rated_restaurant = restaurant

for hotel in all_hotels.split(","):
    if top_rated_hotel is None:
        top_rated_hotel = hotel
    else:
        hotel_price = get_hotels_prices([hotel])
        top_rated_hotel_price = get_hotels_prices([top_rated_hotel])
        if hotel in hotel_price and top_rated_hotel in top_rated_hotel_price:
            if hotel_price[hotel] < top_rated_hotel_price[top_rated_hotel]:
                top_rated_hotel = hotel

# Get the ratings and addresses of the restaurant and hotel
restaurant_rating = get_rating_reviews_for_restaurants([top_rated_restaurant])
restaurant_address = get_restaurants_address([top_rated_restaurant])
hotel_rating = get_rating_reviews_for_hotels([top_rated_hotel])
hotel_address = get_hotels_address(top_rated_hotel)

# Print the names, ratings, and addresses of the restaurant and hotel
print("Top-rated restaurant:")
print("Name:", top_rated_restaurant)
if top_rated_restaurant in restaurant_rating:
    print("Rating:", restaurant_rating[top_rated_restaurant])
if top_rated_restaurant in restaurant_address:
    print("Address:", restaurant_address[top_rated_restaurant])

print("\nTop-rated hotel:")
print("Name:", top_rated_hotel)
if top_rated_hotel in hotel_rating:
    print("Rating:", hotel_rating[top_rated_hotel])
if top_rated_hotel in hotel_address:
    print("Address:", hotel_address[top_rated_hotel])
